import type { PaginationProps } from "./pagination.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Pagination";

// Generate child element class names for the component, should match available style slots
export const PaginationClasses = {
  root: "exp-textura_pagination",
  ellipsis: "exp-textura_pagination_ellipsis",
  prevButton: "exp-textura_pagination_prev_button",
  nextButton: "exp-textura_pagination_next_button",
  pageButton: "exp-textura_pagination_page_button",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: PaginationProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<PaginationProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    alignItems: "center",
    gap: theme.toRem(theme.spacing[4]),

    [`& .${PaginationClasses.ellipsis}[disabled]`]: {
      height: theme.toRem(32),
      width: theme.toRem(32),
      pointerEvents: "none",
      backgroundColor: "transparent",
      opacity: "1",
      color: theme.button.primary.color.content.disabled,
      border: "none",
      ...styleSlots?.ellipsis,
    },

    [`& .${PaginationClasses.prevButton}`]: {
      ":dir(rtl)": {
        transform: "rotate(180deg)",
      },
      "&:disabled, &:disabled:hover": {
        cursor: "default",
        ...styleSlots?.prevButtonDisabled,
      },
      ...styleSlots?.prevButton,
    },

    [`& .${PaginationClasses.nextButton}`]: {
      ":dir(rtl)": {
        transform: "rotate(180deg)",
      },
      "&:disabled, &:disabled:hover": {
        cursor: "default",
        ...styleSlots?.nextButtonDisabled,
      },
      ...styleSlots?.nextButton,
    },

    [`& .${PaginationClasses.pageButton}`]: {
      height: theme.toRem(32),
      width: theme.toRem(32),
      "&[data-selected]": {
        cursor: "default",
        ...styleSlots?.pageButtonSelected,
      },
      ...styleSlots?.pageButton,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps("start", "finish", "spread");

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledPagination = styled("nav", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<PaginationProps>((props) => generateStyles(props));
